#!/usr/bin/env bash
# Generates release-docs/components.md: which Kubernetes resources the sedai-smart-agent chart
# installs by default, and which ones each top-level `<component>.enabled` toggle in values.yaml
# adds (or removes, for toggles that default to true).
#
# Usage: .github/scripts/component-matrix.sh [chart-dir] [output-file]
set -euo pipefail
export LC_ALL=C  # stable sort/comm order across macOS and Linux runners

CHART=${1:-charts/sedai-smart-agent}
OUT=${2:-release-docs/components.md}
RELEASE=sedai
NAMESPACE=sedai

# Placeholder values the chart refuses to render without. They don't change which resources render.
BASE_SETS="workload.smartAgent.secret=placeholder,sedaiIntegrationSettings.sedaiBaseUrl=https://app.sedai.io"

WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT

# Prints one "Kind|name|template" line per rendered resource, sorted.
render() {
  local sets=$1 out=$2
  helm template "$RELEASE" "$CHART" -n "$NAMESPACE" --set "$sets" > "$WORK/render.yaml" 2> "$WORK/render.err" || return 1
  awk '
    function flush() { if (kind != "" && name != "") print kind "|" name "|" src; kind = ""; name = ""; inmeta = 0 }
    /^---/                   { flush(); next }
    /^# Source: /            { src = $3; sub(/^[^\/]*\//, "", src); next }
    /^kind:/                 { kind = $2; next }
    /^metadata:/             { inmeta = 1; next }
    inmeta && /^  name:/     { name = $2; gsub(/["\047]/, "", name); next }
    /^[^ #]/                 { inmeta = 0 }
    END                      { flush() }
  ' "$WORK/render.yaml" | sort -u > "$out"
}

table() {
  echo "| Kind | Name | Template |"
  echo "|---|---|---|"
  awk -F'|' '{ printf "| %s | `%s` | `%s` |\n", $1, $2, $3 }' "$1"
}

# Top-level keys with an `enabled:` directly under them: "key|default|comment"
awk '
  /^[a-zA-Z]/ { top = $1; sub(/:.*/, "", top) }
  /^  enabled:/ {
    split($0, parts, "#"); comment = (length(parts) > 1) ? substr($0, index($0, "#") + 1) : ""
    gsub(/^ +| +$/, "", comment)
    print top "|" $2 "|" comment
  }
' "$CHART/values.yaml" > "$WORK/toggles"

render "$BASE_SETS" "$WORK/default" || { cat "$WORK/render.err" >&2; exit 1; }

VERSION=$(awk '/^version:/ { print $2 }' "$CHART/Chart.yaml")
APP_VERSION=$(awk '/^appVersion:/ { gsub(/"/, "", $2); print $2 }' "$CHART/Chart.yaml")

{
  echo "# Sedai Smart Agent: what each component installs"
  echo
  echo "_Generated by \`.github/scripts/component-matrix.sh\` from \`$CHART/values.yaml\`, chart version \`$VERSION\` (app \`$APP_VERSION\`). Do not edit by hand. It is regenerated on every push to \`dev\` that changes the chart._"
  echo
  echo "Each toggle below is rendered with \`helm template\` on its own, with every other value at its default, and compared against the default install. Resource names assume release name \`$RELEASE\`."
  echo
  echo "## Summary"
  echo
  echo "| Toggle | Default | Resources it controls | Description |"
  echo "|---|---|---|---|"
} > "$WORK/summary"
: > "$WORK/details"

while IFS='|' read -r key default comment; do
  if [ "$default" = "true" ]; then flip=false; else flip=true; fi
  if render "$BASE_SETS,$key.enabled=$flip" "$WORK/flipped"; then
    if [ "$flip" = "true" ]; then
      comm -13 "$WORK/default" "$WORK/flipped" > "$WORK/delta"
    else
      comm -23 "$WORK/default" "$WORK/flipped" > "$WORK/delta"
    fi
    count=$(wc -l < "$WORK/delta" | tr -d ' ')
    status=$count
  else
    status="render fails"
    count=0
  fi
  echo "| [\`$key.enabled\`](#$(echo "$key" | tr '[:upper:]' '[:lower:]')) | \`$default\` | $status | ${comment:-} |" >> "$WORK/summary"

  {
    echo "### $key"
    echo
    echo "\`$key.enabled\`, default \`$default\`.${comment:+ $comment}"
    echo
    if [ "$status" = "render fails" ]; then
      echo "Setting it to \`$flip\` with no other values fails to render, so it needs more values to be set:"
      echo
      echo '```'
      grep -v '^$' "$WORK/render.err" | head -5
      echo '```'
    elif [ "$count" -eq 0 ]; then
      echo "Adds no Kubernetes resources. It only changes the configuration of resources that are already installed."
    else
      if [ "$default" = "true" ]; then
        echo "Installed by default. Setting it to \`false\` removes:"
      else
        echo "Setting it to \`true\` adds:"
      fi
      echo
      table "$WORK/delta"
    fi
    echo
  } >> "$WORK/details"
done < "$WORK/toggles"

mkdir -p "$(dirname "$OUT")"
{
  cat "$WORK/summary"
  echo
  echo "## Default install"
  echo
  echo "What \`helm install\` creates with \`values.yaml\` as shipped ($(wc -l < "$WORK/default" | tr -d ' ') resources):"
  echo
  table "$WORK/default"
  echo
  echo "## Per component"
  echo
  cat "$WORK/details"
} > "$OUT"

echo "Wrote $OUT"
